import { useState } from "react";
import type { ReactNode } from "react";
import { Pressable, ScrollView, StyleSheet, Text, View } from "react-native";
import type { StyleProp, TextStyle, ViewProps, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface TabItem {
  value: string;
  label: string;
  disabled?: boolean;
  content: ReactNode;
}

export interface TabsProps extends ViewProps {
  items: TabItem[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Extend the inner, named parts of the tabs: list, trigger, selection, label or content. The React Native counterpart of `classNames`. */
  styles?: {
    list?: StyleProp<ViewStyle>;
    trigger?: StyleProp<ViewStyle>;
    selection?: StyleProp<ViewStyle>;
    label?: StyleProp<TextStyle>;
    content?: StyleProp<ViewStyle>;
  };
}

/** Unlike the web version, which is a set of parts, React Native takes the tabs as data: each item carries its own panel. */
export function Tabs({ items, value, defaultValue, onValueChange, style, styles: parts, ...props }: TabsProps) {
  const tokens = useTokens();
  const [internal, setInternal] = useState(defaultValue ?? items[0]?.value);
  const active = value ?? internal;
  const panel = items.find((item) => item.value === active);

  return (
    <View {...props} style={[{ alignSelf: "stretch" }, style]}>
      <ScrollView horizontal showsHorizontalScrollIndicator={false} style={local.scroll}>
        <View
          accessibilityRole="tablist"
          style={[local.list, { borderColor: tokens.border, backgroundColor: tokens.surfaceMuted }, parts?.list]}
        >
          {items.map((item) => {
            const selected = item.value === active;
            return (
              <Pressable
                key={item.value}
                accessibilityRole="tab"
                accessibilityState={{ selected, disabled: item.disabled }}
                disabled={item.disabled}
                onPress={() => {
                  if (value === undefined) setInternal(item.value);
                  onValueChange?.(item.value);
                }}
                style={[
                  local.trigger,
                  selected && { borderColor: tokens.border, backgroundColor: tokens.surface },
                  item.disabled && { opacity: 0.5 },
                  parts?.trigger,
                  selected && parts?.selection,
                ]}
              >
                <Text style={[{ color: selected ? tokens.accentStrong : tokens.textSecondary, fontSize: metrics.text.sm, fontWeight: "500" }, parts?.label]}>{item.label}</Text>
              </Pressable>
            );
          })}
        </View>
      </ScrollView>
      {panel ? (
        <View accessibilityRole="none" style={[local.content, parts?.content]}>
          {panel.content}
        </View>
      ) : null}
    </View>
  );
}

const local = StyleSheet.create({
  scroll: { flexGrow: 0 },
  list: { flexDirection: "row", alignItems: "center", gap: metrics.space[1], padding: metrics.space[1], borderWidth: 1, borderRadius: metrics.radiusControl },
  trigger: {
    minWidth: 88,
    minHeight: metrics.controlHeight.sm,
    paddingHorizontal: metrics.space[3],
    alignItems: "center",
    justifyContent: "center",
    borderWidth: 1,
    borderColor: "transparent",
    borderRadius: metrics.radiusControl - 3,
  },
  content: { marginTop: metrics.space[4] },
});

export default Tabs;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
  /** Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4. */
  series: [string, string, string, string];
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
  series: ["#1f7dcf", "#7128a5", "#e58f00", "#009e84"],
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
  series: ["#55adff", "#9c37be", "#e66e00", "#00a861"],
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
